import assert from "node:assert/strict";
import test from "node:test";

import { parsePort } from "../src/parse.js";

test("a port has to be an integer", () => {
  assert.equal(parsePort("8080"), 8080);
});

test("trailing text is not a port", () => {
  assert.throws(() => parsePort("8080abc"), /port out of range/);
});

test("zero is out of range", () => {
  assert.throws(() => parsePort("0"), /port out of range/);
});

